using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "SapphireFishingRodOmenData", menuName = "Data/Battle/Omens System/Omen Data/Cellarius/SapphireFishingRodOmenData", order = 0)]
public class SapphireFishingRodOmenData : OmenData
{
	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<CellariusOmensHandler>.Instance.SapphireFishingRodOmenAction = delegate(int effectAmount)
		{
			omenInstance.ActivateOmenFeedback();
			return effectAmount + ActionValue;
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<CellariusOmensHandler>.Instance.SapphireFishingRodOmenAction = null;
	}
}
